import zlib, re, os, sys, codecs

D = r"C:\Users\Admin\Documents\GitHub\BRICS-Skills-Competition\Official_Document"
FILES = sorted(f for f in os.listdir(D) if f.endswith(".pdf"))

def get_objects(data):
    objs = {}
    for m in re.finditer(rb"(\d+)\s+0\s+obj\b(.*?)endobj", data, re.DOTALL):
        objs[int(m.group(1))] = m.group(2)
    return objs

def get_stream(body):
    m = re.search(rb"stream\r?\n(.*?)endstream", body, re.DOTALL)
    if not m: return None
    s = m.group(1)
    if s.startswith(b"\r\n"): s = s[2:]
    elif s.startswith(b"\n") or s.startswith(b"\r"): s = s[1:]
    if s.endswith(b"\n"): s = s[:-1]
    try:
        return zlib.decompress(s)
    except Exception:
        return s

def parse_cmap(body):
    cmap = {}
    cs = 1
    stream = get_stream(body) or b""
    m = re.search(rb"begincodespacerange\s*(.*?)endcodespacerange", stream, re.DOTALL)
    if m:
        m2 = re.search(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", m.group(1))
        if m2: cs = len(m2.group(1)) // 2
    for m in re.finditer(rb"beginbfchar\s*(.*?)endbfchar", stream, re.DOTALL):
        for line in m.group(1).splitlines():
            mm = re.match(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", line.strip())
            if mm:
                try:
                    dst = bytes.fromhex(mm.group(2).decode()).decode("utf-16-be")
                    cmap[bytes.fromhex(mm.group(1).decode())] = dst
                except Exception: pass
    for m in re.finditer(rb"beginbfrange\s*(.*?)endbfrange", stream, re.DOTALL):
        for line in m.group(1).splitlines():
            line = line.strip()
            mm = re.match(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>", line)
            if mm:
                lo = int(mm.group(1), 16); hi = int(mm.group(2), 16); st = int(mm.group(3), 16)
                if hi - lo > 50000: continue
                for c in range(lo, hi + 1):
                    try: cmap[c.to_bytes(cs, "big")] = chr(st + (c - lo))
                    except Exception: pass
                continue
            mm = re.match(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*\[(.*?)\]", line, re.DOTALL)
            if mm:
                lo = int(mm.group(1), 16); hi = int(mm.group(2), 16)
                dsts = re.findall(rb"<([0-9A-Fa-f]+)>", mm.group(3))
                for i, c in enumerate(range(lo, hi + 1)):
                    if i >= len(dsts): break
                    try: cmap[c.to_bytes(cs, "big")] = bytes.fromhex(dsts[i].decode()).decode("utf-16-be")
                    except Exception: pass
    return cmap, cs

def find_pages(objs):
    pages = []
    def walk(n, depth=0):
        if depth > 12 or n not in objs: return
        body = objs[n]
        if re.search(rb"/Type\s*/\s*Page\b", body):
            pages.append((n, body))
            return
        if re.search(rb"/Type\s*/\s*Pages\b", body):
            for m in re.finditer(rb"(\d+)\s+0\s+R", body):
                walk(int(m.group(1)), depth + 1)
    roots = [n for n, b in objs.items() if re.search(rb"/Type\s*/\s*Pages\b", b)]
    for r in roots: walk(r)
    seen = set(); out = []
    for p in pages:
        if p[0] not in seen: seen.add(p[0]); out.append(p)
    if not out:
        out = [(n, b) for n, b in objs.items() if re.search(rb"/Type\s*/\s*Page\b", b)]
    return out

def font_cmaps(objs):
    fm = {}
    for n, body in objs.items():
        if re.search(rb"/Type\s*/\s*Font\b", body):
            m = re.search(rb"/ToUnicode\s+(\d+)\s+0\s+R", body)
            if m:
                tgt = int(m.group(1))
                if tgt in objs:
                    cmap, cs = parse_cmap(objs[tgt])
                    if cmap: fm[n] = (cmap, cs)
    return fm

def decode_lit(s):
    s = s[1:-1]
    def rep(m):
        c = m.group(1)
        if c in b"nrtbf": return {b"n": "\n", b"r": "\r", b"t": "\t", b"b": "\b", b"f": "\f"}[c]
        if c in b"()\\": return c.decode()
        if re.match(rb"[0-7]{1,3}$", c): return chr(int(c, 8))
        return ""
