    try: raw = bytes.fromhex(hx.decode())
    except Exception: return ""
    out = []; pos = 0
    while pos < len(raw):
        found = False
        for L in range(min(4, len(raw) - pos), 0, -1):
            key = raw[pos:pos + L]
            if key in cmap:
                out.append(cmap[key]); pos += L; found = True; break
        if not found:
            out.append("?"); pos += max(1, cs)
    return "".join(out)

TOKEN = re.compile(rb"""<<[^>]*>>|\[[^\[\]]*\]|\((?:\\.|[^()\\])*\)|<[0-9A-Fa-f\s]*[0-9A-Fa-f][0-9A-Fa-f\s]*>|-?(?:\d+\.?\d*|\.\d+)|[A-Za-z0-9*/+.#$_-]+|['"]""", re.VERBOSE)

def page_text(objs, fonts, pageno, body):
    m = re.search(rb"/Contents\s+(\d+)\s+0\s+R", body)
    chunks = []
    if not m: return ""
    stack = []; x = 0.0; y = 0.0; size = 10.0; leading = 12.0; curf = None
    def show(s, cmap, cs):
        nonlocal x, y
        if isinstance(s, bytes):
            if s.startswith(b"<"): txt = decode_hex(s, cmap, cs)
            else: txt = decode_lit(s)
        else: txt = s
        if txt: chunks.append((x, y, txt))
        x += len(txt) * size * 0.5
    for cn in re.findall(rb"(\d+)\s+0\s+R", m.group(1)):
        if int(cn) not in objs: continue
        st = get_stream(objs[int(cn)])
        if not st: continue
        tokens = TOKEN.findall(st)
        i = 0
        while i < len(tokens):
            t = tokens[i]
            if t == b"Tj" and stack:
                s = stack.pop(); f = fonts.get(curf)
                if f: show(s, f[0], f[1])
            elif t == b"TJ" and stack:
                arr = stack.pop()
                f = fonts.get(curf)
                for item in re.findall(rb"<[0-9A-Fa-f\s]*[0-9A-Fa-f][0-9A-Fa-f\s]*>|\((?:\\.|[^()\\])*\)|-?\d+\.?\d*", arr):
                    if re.match(rb"-?\d", item): x -= float(item) * size / 1000.0
                    elif f: show(item, f[0], f[1])
            elif t == b"'" and stack:
                s = stack.pop(); y -= leading; f = fonts.get(curf)
                if f: show(s, f[0], f[1])
            elif t == b'"' and len(stack) >= 3:
                stack.pop(); stack.pop(); s = stack.pop(); y -= leading; f = fonts.get(curf)
                if f: show(s, f[0], f[1])
            elif t == b"Tm" and len(stack) >= 6:
                e = float(stack[-2]); f_ = float(stack[-1]); del stack[-6:]
                x, y = e, f_
            elif t in (b"Td", b"TD") and len(stack) >= 2:
                ty = float(stack.pop()); tx = float(stack.pop()); x += tx; y += ty
                if t == b"TD": leading = -ty
            elif t == b"T*":
                y -= leading
            elif t == b"Tf" and len(stack) >= 2:
                size = float(stack.pop()); curf = stack.pop()
                if isinstance(curf, bytes):
                    mm = re.match(rb"/?([A-Za-z0-9]+)$", curf)
                    if mm:
                        key = mm.group(1).decode()
                        # map resource name via page resources
                        if curf.startswith(b"/"):
                            rm = re.search(rb"/Font\s*<<(.*?)>>", body)
                            if rm:
                                fm2 = re.search(rb"/" + re.escape(key.encode()) + rb"\s+(\d+)\s+0\s+R", rm.group(1))
                                if fm2 and int(fm2.group(1)) in fonts: curf = int(fm2.group(1))
            elif t == b"BT":
                stack = []
            elif t == b"ET":
                stack = []
            elif t == b"cm" and len(stack) >= 6:
                e = float(stack[-2]); f_ = float(stack[-1]); del stack[-6:]
                # CTM translation: apply to cursor at next BT
            else:
                stack.append(t)
            i += 1
    if not chunks: return ""
    lines = []
    chunks.sort(key=lambda c: (-round(c[1] * 2) / 2, c[0]))
    cur_y = None; cur_line = ""
    for cx, cy, txt in chunks:
        if cur_y is None or abs(cy - cur_y) > 2.5:
            if cur_line: lines.append(cur_line)
            cur_y = cy; cur_line = txt
        else:
            if cur_line and cur_line[-1].isascii() and txt and txt[0].isascii() and cur_line[-1].isalnum() and txt[0].isalnum():
                cur_line += " "
            cur_line += txt
    if cur_line: lines.append(cur_line)
    return "\n".join(lines)

def main():
    print("[0] 赛题 | [1] 技术规程 | [2] 评分标准 | [3] 通知")
    if len(sys.argv) < 2: return
    idx = int(sys.argv[1])
    data = open(os.path.join(D, FILES[idx]), "rb").read()
    objs = get_objects(data)
    fonts = font_cmaps(objs)
    pages = find_pages(objs)
    if len(sys.argv) >= 3 and sys.argv[2] == "info":
        print(f"{FILES[idx]}: {len(pages)} pages")
        for pi, (n, body) in enumerate(pages, 1):
            t = page_text(objs, fonts, n, body)
            prev = t.replace("\n", " / ")[:150]
            print(f"--- p{pi}: {prev}")
        return
    lo = int(sys.argv[2]) if len(sys.argv) >= 3 else 1
    hi = int(sys.argv[3]) if len(sys.argv) >= 4 else lo
    for pi, (n, body) in enumerate(pages, 1):
        if pi < lo or pi > hi: continue
        print(f"\n===== {FILES[idx]} | 第{pi}页 =====\n")
        print(page_text(objs, fonts, n, body))

